def top_words(text: str, n: int) -> list[tuple[str, int]]:
    if n <= 0:
        return []

    words = []
    current = []
    for ch in text:
        if ch.isalpha():
            current.append(ch.lower())
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))

    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1

    sorted_words = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return sorted_words[:n]
```

